import { PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Destructure config with defaults
  const {
    imageUrl = '/prism-assets/chrome/ceramic-grain.map.png',
    visual = {},
    scenePlacement = { position: [0, -0.3, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
  } = config;

  // Compute aspect ratio from atlas region (512x320 → 1.6)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspect = atlasWidth / atlasHeight;

  // Create geometry sized to aspect ratio (width = aspect, height = 1)
  const geometry = new PlaneGeometry(aspect, 1);

  // Load texture (assumed synchronous from cache)
  const mapTexture = ctx.textureLoader(imageUrl);

  // Create material with node-based map
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(mapTexture),
    transparent: true,
    depthWrite: false,
  });

  // Build mesh
  const mesh = new Object3D();
  mesh.geometry = geometry;
  mesh.material = material;

  // Apply scene placement
  const { position, rotation, scale } = scenePlacement;
  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // Billboard via onBeforeRender (always face camera)
  mesh.onBeforeRender = (_renderer, _scene, camera) => {
    mesh.lookAt(camera.position);
  };

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    mapTexture.dispose();
    // Remove onBeforeRender to avoid memory leak
    delete mesh.onBeforeRender;
  };

  // No text content, no handlers, no primitives
  mesh.userData.handlers = {};

  return mesh;
}
